Here's how to handle each scenario with modern MSTest (3.9+):

```csharp
[TestClass]
public sealed class PlatformAndEnvironmentTests
{
    private readonly TestContext _testContext;
    private string? _tempFilePath;

    public PlatformAndEnvironmentTests(TestContext testContext)
    {
        _testContext = testContext;
    }

    // 1. Windows-only: skipped automatically on Linux/macOS
    [TestMethod]
    [OSCondition(OperatingSystems.Windows)]
    public void ReadRegistryKey_ReturnsExpectedValue()
    {
        var value = Registry.GetValue(@"HKEY_LOCAL_MACHINE\SOFTWARE\MyApp", "Version", null);
        Assert.IsNotNull(value);
    }

    // 2. Skip in CI: runs only on local dev machines
    [TestMethod]
    [CICondition(ConditionMode.Exclude)]
    [Timeout(30000)]
    public async Task GpuRender_ProducesValidOutput()
    {
        var result = await GpuRenderer.RenderAsync(_testContext.CancellationToken);
        Assert.IsNotNull(result);
    }

    // 3. Flaky external API: retry up to 3 times
    [TestMethod]
    [Retry(3)]
    [Timeout(10000)]
    public async Task WeatherApi_ReturnsForecast()
    {
        var forecast = await WeatherClient.GetForecastAsync("Seattle",
            _testContext.CancellationToken);
        Assert.IsNotNull(forecast);
        Assert.IsNotEmpty(forecast.Days);
    }

    // 4. Temp file cleanup: [TestCleanup] runs even on failure
    [TestMethod]
    public void ExportReport_WritesValidFile()
    {
        _tempFilePath = Path.Combine(Path.GetTempPath(), $"{Guid.NewGuid()}.csv");

        ReportExporter.Export(_tempFilePath);

        Assert.IsTrue(File.Exists(_tempFilePath));
        var content = File.ReadAllText(_tempFilePath);
        Assert.Contains("Header", content);
    }

    [TestCleanup]
    public void Cleanup()
    {
        if (_tempFilePath is not null && File.Exists(_tempFilePath))
        {
            File.Delete(_tempFilePath);
        }
    }
}
```

**Summary of attributes used:**

| Scenario | Attribute | Min Version |
|---|---|---|
| Windows-only | `[OSCondition(OperatingSystems.Windows)]` | 3.10+ |
| Skip in CI | `[CICondition(ConditionMode.Exclude)]` | 3.10+ |
| Flaky API | `[Retry(3)]` | 3.9+ |
| Cleanup on failure | `[TestCleanup]` | Any |

**Key points:**
- `[Retry]` is for genuinely flaky external dependencies — don't use it to mask race conditions.
- `[TestCleanup]` always runs (even on test failure), making it ideal for resource cleanup.
- Combine `[Timeout]` with `TestContext.CancellationToken` for async tests so they cancel cooperatively.
